import heapq

def merge_sorted_streams(*streams):
    streams = [stream for stream in streams]  # Convert to list if not already
    heap = []
    stream_iters = [iter(stream) for stream in streams]
    for i, it in enumerate(stream_iters):
        try:
            key, value = next(it)
            heapq.heappush(heap, (key, i, value, it))
        except StopIteration:
            pass

    while heap:
        key, stream_index, value, it = heap[0]
        try:
            next_key, next_value = next(it)
            if next_key == key:
                heap[0] = (key, stream_index, next_value, it)
            else:
                heapq.heappop(heap)
                heapq.heappush(heap, (next_key, stream_index, next_value, it))
        except StopIteration:
            heapq.heappop(heap)
        yield key, value
